pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount) public {
        // Bound to a reasonable non-zero amount to ensure a positive balance
        depositAmount = bound(depositAmount, 1, 100 ether);

        // Send Ether to the contract to establish a positive balance
        vm.deal(address(this), depositAmount);
        (bool success, ) = address(c).call{value: depositAmount}("");
        require(success, "Initial deposit failed");

        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Owner calls withdrawAll
        vm.prank(owner);
        c.withdrawAll();

        uint256 ownerBalanceAfter = owner.balance;
        uint256 contractBalanceAfter = address(c).balance;

        // General rule: if the contract had a positive balance before, the owner's balance must increase after withdrawAll.
        // The reference C transfers the full balance, so owner's balance increases. The buggy version leaves the balance in the contract,
        // so the owner's balance does not increase.
        assertTrue(ownerBalanceAfter > ownerBalanceBefore);
    }
}

