pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. admissible domain: positive sendable amount
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance);

        // 2. set up: fund the contract via fallback to increment depositsCount
        vm.deal(address(this), amount * 2);
        // send Ether to contract via fallback (increments depositsCount)
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "initial funding failed");
        // ensure depositsCount > 0 after fallback
        assert(c.depositsCount() > 0);

        // 3. record pre-state balances
        uint256 preOwnerBal = c.owner().balance;
        uint256 preContractBal = address(c).balance;

        // 4. make the owner call withdrawAll
        vm.prank(c.owner());
        try c.withdrawAll() {
            // success path
        } catch {}

        // 5. post-state balances
        uint256 postOwnerBal = c.owner().balance;
        uint256 postContractBal = address(c).balance;

        // 6. GENERAL RULE: after withdrawAll, if depositsCount remains > 0 (no zeroing logic in reference),
        // the owners balance must increase by exactly the previous contract balance
        // and the contract balance must become zero (reference transfers full balance).
        // Bug breaks this because it's a no-op: owner balance unchanged, contract balance unchanged.
        bool invariantHolds = (postOwnerBal >= preOwnerBal + amount) && (postContractBal == 0);
        assertTrue(invariantHolds, "withdrawAll failed to transfer balance to owner");
    }
}

