pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 depositAmount, address other) public {
        // Bound depositAmount to a reasonably wide range
        depositAmount = bound(depositAmount, 1, 100 ether);

        // Ensure the other address is not the owner to avoid accidental pranks on owner later
        vm.assume(other != address(this));
        vm.assume(other != address(c));

        // Fund the contract by sending ETH from any address
        vm.deal(other, depositAmount);
        vm.prank(other);
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "setup failed");

        // Record balance before withdrawAll
        uint256 balanceBefore = address(c).balance;
        // Owner (this contract) calls withdrawAll
        vm.prank(address(this));
        c.withdrawAll();

        // After a successful withdrawAll by owner, the contract’s ETH balance must be strictly less than before.
        // Reference C satisfies this (sends entire balance to owner); buggy C sends 0 so balance remains unchanged.
        assertTrue(address(c).balance < balanceBefore);
    }
}

