pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0x1);

    function setUp() public {
        vm.prank(owner);
        c = new C();
    }

    function testFuzz_property(uint256 depositAmount) public {
        // Restrict depositAmount to a range that avoids overflow and is practical for funding
        vm.assume(depositAmount > 0 && depositAmount <= 10_000 ether);

        // Fund the contract with ether from the owner
        vm.deal(owner, depositAmount);
        vm.prank(owner);
        (bool ok, ) = address(c).call{value: depositAmount}("");
        require(ok, "initial funding failed");

        // Record balances before withdrawAll
        uint256 contractBalBefore = address(c).balance;
        uint256 ownerBalBefore = owner.balance;

        // Call withdrawAll as owner
        vm.prank(owner);
        c.withdrawAll();

        // Read balances after
        uint256 contractBalAfter = address(c).balance;
        uint256 ownerBalAfter = owner.balance;

        // Property: contract balance decreases exactly by the amount that was able to be sent (pre-call balance),
        // and the owner balance increases by that same amount.
        // The correct implementation transfers the whole contract balance; thus contractBalAfter should be 0
        // and ownerBalAfter - ownerBalBefore should equal contractBalBefore.
        // The bug transfers 0, so contract balance stays unchanged and owner balance does not increase.
        assertTrue(contractBalAfter == 0 && (ownerBalAfter - ownerBalBefore) == contractBalBefore);
    }
}

