pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address attacker, address target, uint256 value, bytes calldata data) public {
        vm.assume(attacker != address(0));
        vm.assume(target != address(0));
        vm.assume(attacker != c.owner());
        vm.assume(value <= address(c).balance);

        // Fund contract via deposition from owner to have a positive balance
        vm.deal(c.owner(), 100 ether);
        vm.prank(c.owner());
        (bool ok,) = address(c).call{value: 100 ether}("");
        require(ok, "deposit failed");

        uint256 balanceBefore = address(c).balance;

        // attacker cannot call withdrawAll because of onlyOwner
        vm.prank(attacker);
        try c.withdrawAll() { assert(false); } catch {}

        // attacker can call withdraw directly (unprotected in buggy version)
        vm.prank(attacker);
        try c.withdraw(value) {} catch {}

        uint256 balanceAfter = address(c).balance;

        // Correct property: a non-owner cannot reduce the balance through a direct withdraw
        // In reference C this holds (withdrawAll and withdraw have onlyOwner),
        // but in buggy C withdraw is public for anyone, so balance may drop.
        assertTrue(balanceAfter == balanceBefore, "non-owner should not affect balance via withdraw");
    }
}

