pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, uint256 amount, bytes memory data) public {
        vm.assume(nonOwner != address(this) && nonOwner != address(c));
        amount = bound(amount, 1, 100 ether);
        // Deal Ether to c so the contract has a balance that can be drained.
        vm.deal(address(c), amount);
        // Give nonOwner some Ether for gas.
        vm.deal(nonOwner, 1 ether);
        // Prerequisite: nonOwner is not the owner.
        vm.assume(c.owner() != nonOwner);
        // nonOwner calls sendMoney to satisfy the "after sendMoney" precondition;
        // the target can be itself, but the call may fail depending on _data.
        vm.prank(nonOwner);
        try c.sendMoney(nonOwner, 0, data) {} catch {}
        // Now nonOwner attempts to withdraw the full balance directly.
        uint256 balBefore = address(c).balance;
        vm.prank(nonOwner);
        try c.withdraw(balBefore) {} catch {}
        // After the attempt, assert: a non-owner cannot reduce the contract balance below balBefore.
        // In the reference (onlyOwner protected), the withdraw reverts, so balance stays balBefore.
        // In the buggy mutant (unprotected withdraw), it succeeds, making balance < balBefore.
        assertTrue(address(c).balance >= balBefore);
    }
}

