pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller) public {
        // keep amount in a wide but safe range
        vm.assume(amount > 0 && amount <= address(this).balance / 2);
        vm.assume(caller != address(this));

        // deploy a balance-observing helper that is the owner
        BalanceSink owner_sink = new BalanceSink(caller);
        // transfer ownership to the sink
        vm.prank(address(this));
        c.sendMoney(address(0), 0, ""); // no-op to ensure ownership already this
        // use a low-level call to transfer ownership since no method
        // we can exploit onlyOwner to set by topping up
        // Actually set owner via a call from the current owner
        // Current owner is address(this), we can prank as this
        // But we need to set owner to owner_sink. No setter exists.
        // We can send money to induce balance for withdraw
        // We'll fund c with enough ether
        vm.deal(address(c), amount * 2);
        // prank as the sink to call withdraw? Sink is owner after ownership transfer impossible without method.
        // The only way to change owner is via constructor or no way. Given no setOwner, owner is deployer.
        // We'll use a helper that is the deployer and observes own balance.
        // Since owner is fixed as address(this) (deployer of C), we must use address(this) as owner.
        // So we deploy a helper that is the owner and records starting balance.
        // But owner is address(this) already.
