pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, bytes calldata data) public {
        // Bound amount to keep it within the contract's balance to avoid reverts on insufficient balance
        vm.deal(address(c), 1000 ether);
        vm.assume(amount <= 1000 ether);
        // Deploy adversarial helper that records its balance before and after the call
        BalanceRecorder target = new BalanceRecorder();
        vm.deal(address(target), 0);

        // Record initial balances
        uint256 contractBalanceBefore = address(c).balance;
        uint256 targetBalanceBefore = address(target).balance;

        // Owner calls sendMoney
        vm.prank(c.owner());
        c.sendMoney(address(target), amount, data);

        // Record final balances
        uint256 contractBalanceAfter = address(c).balance;
        uint256 targetBalanceAfter = address(target).balance;

        // The general rule: contract balance decrease + target balance increase == amount sent
        // (gas costs are paid by the owner, not the contract, so they don't affect contract balance)
        // For the correct version, this holds because the call transfers value.
        // For the buggy version, the RHS is 0 but LHS is (contractBalanceBefore - contractBalanceAfter) + (targetBalanceAfter - targetBalanceBefore),
        // which will be 0 for the buggy version; the rule fails because it expects amount to be transferred.
        assertTrue(
            (contractBalanceBefore - contractBalanceAfter) + (targetBalanceAfter - targetBalanceBefore) == amount
        );
    }
}

contract BalanceRecorder {
    // Minimal helper that simply accepts Ether; acts as a passive target whose balance can be observed.
    fallback() external payable {}
}

